# Hypothesis: Complete each section fully with its color
grid = [
    [8, 8, 8, 0, 3, 5, 0, 5, 5, 3, 9, 0, 0, 0, 3, 0, 0, 0, 0],
    [8, 0, 8, 8, 3, 5, 5, 5, 5, 3, 0, 0, 9, 9, 3, 4, 4, 0, 4],
    [8, 0, 0, 8, 3, 5, 0, 5, 5, 3, 0, 0, 0, 9, 3, 0, 4, 0, 4],
    [0, 0, 8, 8, 3, 0, 0, 5, 5, 3, 9, 9, 9, 0, 3, 0, 4, 4, 0]
]

sections = [(0, 3), (5, 8), (10, 13), (15, 18)]
colors = [8, 5, 9, 4]

# Build output: fill each section completely
output = [[0]*19 for _ in range(4)]
for r in range(4):
    for c in range(19):
        # Find which section column belongs to
        sec_start = None
        for start, end in sections:
            if start <= c <= end:
                sec_start = start
                break
        if sec_start is not None:
            # Determine color based on original row's pattern
            # Actually let's just copy the non-zero values and zero out everything else first
            pass

# Simpler: just replicate original pattern but fill all zeros in sections
output = [[0]*19 for _ in range(4)]
for r in range(4):
    output[r] = list(grid[r])

# Now fill in each section completely
for sec_idx, (start, end) in enumerate(sections):
    color = colors[sec_idx]
    for r in range(4):
        for c in range(start, end+1):
            output[r][c] = color

print("Output with complete sections:")
for row in output:
    print(row)

# Check vertical symmetry possibility
grid = [
    [8, 8, 8, 0, 3, 5, 0, 5, 5, 3, 9, 0, 0, 0, 3, 0, 0, 0, 0],
    [8, 0, 8, 8, 3, 5, 5, 5, 5, 3, 0, 0, 9, 9, 3, 4, 4, 0, 4],
    [8, 0, 0, 8, 3, 5, 0, 5, 5, 3, 0, 0, 0, 9, 3, 0, 4, 0, 4],
    [0, 0, 8, 8, 3, 0, 0, 5, 5, 3, 9, 9, 9, 0, 3, 0, 4, 4, 0]
]

# Build output where top half mirrors bottom half
output = [[0]*19 for _ in range(4)]
for r in range(4):
    for c in range(19):
        val = grid[r][c]
        # Mirror across horizontal center (between row 1 and 2)
        mirror_r = 3 - r
        if val == 0 and mirror_r != r:
            val = grid[mirror_r][c]
        elif val != 0:
            output[r][c] = val
        else:
            output[r][c] = 0

print("Vertical mirror attempt:")
for row in output:
    print(row)

